//! SortedMap: a Rust port of the sortedcontainers-cpp SortedMap interface,
//! backed by std::collections::BTreeMap with lexicographically-ordered tuple keys.

use std::collections::BTreeMap;

pub type Key = (i32, i32);

pub struct SortedMap {
    map: BTreeMap<Key, String>,
}

impl SortedMap {
    pub fn new() -> Self {
        SortedMap {
            map: BTreeMap::new(),
        }
    }

    /// Insert key/value; overwrites if the key already exists
    /// (mirrors Python SortedDict __setitem__).
    pub fn insert(&mut self, key: Key, value: String) {
        self.map.insert(key, value);
    }

    pub fn contains(&self, key: &Key) -> bool {
        self.map.contains_key(key)
    }

    pub fn size(&self) -> usize {
        self.map.len()
    }

    pub fn empty(&self) -> bool {
        self.map.is_empty()
    }

    /// operator[] semantics: value-initialize (empty string) and insert if absent,
    /// then return a reference to the value.
    pub fn index(&mut self, key: &Key) -> &String {
        self.map.entry(*key).or_insert_with(String::new)
    }

    /// operator[] assignment: insert-or-overwrite.
    pub fn index_assign(&mut self, key: &Key, value: &str) {
        self.map.insert(*key, value.to_string());
    }

    pub fn keys(&self) -> Vec<Key> {
        self.map.keys().copied().collect()
    }

    pub fn values(&self) -> Vec<&String> {
        self.map.values().collect()
    }

    pub fn erase(&mut self, key: &Key) -> bool {
        self.map.remove(key).is_some()
    }

    /// find: return Some(&value) if the key exists, else None (like end()).
    pub fn find(&self, key: &Key) -> Option<&String> {
        self.map.get(key)
    }

    /// lower_bound: first entry whose key is not less than `key`.
    pub fn lower_bound(&self, key: &Key) -> Option<(&Key, &String)> {
        self.map.range(*key..).next()
    }

    /// upper_bound: first entry whose key is greater than `key`.
    pub fn upper_bound(&self, key: &Key) -> Option<(&Key, &String)> {
        self.map
            .range((std::ops::Bound::Excluded(*key), std::ops::Bound::Unbounded))
            .next()
    }

    /// equal_range: iterator over entries whose key equals `key` (0 or 1 entries
    /// for a map), mirroring the [lower_bound, upper_bound) pair.
    pub fn equal_range<'a>(
        &'a self,
        key: &Key,
    ) -> std::collections::btree_map::Range<'a, Key, String> {
        self.map.range(*key..=*key)
    }

    /// get with default, like Python's dict.get.
    pub fn get<'a>(&'a self, key: &Key, default: &'a str) -> &'a str {
        self.map.get(key).map(|s| s.as_str()).unwrap_or(default)
    }

    /// update: insert all of `other` into `self`, overwriting duplicates.
    pub fn update(&mut self, other: &SortedMap) {
        for (k, v) in other.map.iter() {
            self.map.insert(*k, v.clone());
        }
    }

    pub fn clear(&mut self) {
        self.map.clear();
    }
}

//! Port of sortedcontainers-cpp/tests/test18.cpp.
//! Compiles both as a cargo binary target and standalone via
//! `rustc --edition 2021 test18.rs` from this directory.

#[path = "src/sortedcontainers.rs"]
mod sortedcontainers;

use sortedcontainers::SortedMap;
use std::io::Write;

/// Mimic C's atoi (glibc: equivalent to (int)strtol(s, NULL, 10)):
/// skip leading whitespace, optional sign, parse digits until a non-digit;
/// saturate at long (i64) range like strtol, then wrap to i32 like the C cast.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let mut acc: i128 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        acc = acc * 10 + (bytes[i] - b'0') as i128;
        // strtol saturates at LONG_MAX/LONG_MIN
        if acc > i64::MAX as i128 {
            acc = i64::MAX as i128;
            break;
        }
        i += 1;
    }
    let val: i64 = if neg { -(acc as i64) } else { acc as i64 };
    val as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 18;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());

    let mut m = SortedMap::new();
    let mut i: i32 = 0;
    while i < n {
        m.insert((i, i.wrapping_mul(2)), format!("value_{}", i));
        i += 1;
    }
    writeln!(out, "{}", m.size()).unwrap();
    let k1 = (3, 6);
    let k2 = (5, 10);
    writeln!(out, "{}", m.contains(&k1) as i32).unwrap();
    writeln!(out, "{}", m.contains(&k2) as i32).unwrap();
    writeln!(out, "{}", m.index(&k1)).unwrap(); // operator[] inserts default "" if absent
    m.index_assign(&k1, "modified");
    writeln!(out, "{}", m.index(&k1)).unwrap();
    writeln!(out, "{}", m.keys().len()).unwrap();
    writeln!(out, "{}", m.values().len()).unwrap();
    for j in 0..4 {
        m.erase(&(j, j * 2));
    }
    writeln!(out, "{}", m.size()).unwrap();
    if let Some(v) = m.find(&(6, 12)) {
        writeln!(out, "{}", v).unwrap();
    }
    if let Some((k, _)) = m.lower_bound(&(7, 14)) {
        writeln!(out, "{}", k.0).unwrap();
    }
    if let Some((k, _)) = m.upper_bound(&(7, 14)) {
        writeln!(out, "{}", k.0).unwrap();
    }

    let mut m2 = SortedMap::new();
    // n/2 is C++ integer division (truncation toward zero)
    let mut i: i32 = 0;
    let half = n / 2; // i32 division in Rust also truncates toward zero
    while i < half {
        let j = i + 10;
        m2.insert((j, j * 2), format!("other_{}", i));
        i += 1;
    }
    m.update(&m2); // inserts all of m2 into m, overwriting duplicates
    writeln!(out, "{}", m.size()).unwrap();
    writeln!(out, "{}", m.contains(&(12, 24)) as i32).unwrap();
    let count = m.equal_range(&(8, 16)).count();
    writeln!(out, "{}", count).unwrap();
    writeln!(out, "{}", m.get(&(100, 200), "default")).unwrap();
    m.clear();
    writeln!(out, "{}", m.size()).unwrap();
    writeln!(out, "{}", m.empty() as i32).unwrap();
}

